import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"TaskFlow API — Backend FastAPI de grado producción","description":"Una API REST de gestión de tareas construida como producción: rotación JWT con detección de reuso, RBAC, rate limiting, caché Redis, suite pytest y Docker Compose.","frontmatter":{"title":"TaskFlow API — Backend FastAPI de grado producción","description":"Una API REST de gestión de tareas construida como producción: rotación JWT con detección de reuso, RBAC, rate limiting, caché Redis, suite pytest y Docker Compose."},"headers":[],"relativePath":"es/projects/taskflow-api/index.md","filePath":"es/projects/taskflow-api/index.md"}`),a={name:`es/projects/taskflow-api/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="taskflow-api-—-backend-fastapi-de-grado-produccion" tabindex="-1">TaskFlow API — Backend FastAPI de grado producción <a class="header-anchor" href="#taskflow-api-—-backend-fastapi-de-grado-produccion" aria-label="Permalink to “TaskFlow API — Backend FastAPI de grado producción”">​</a></h1><p><strong><a href="https://github.com/Godde3s/taskflow-api" target="_blank" rel="noreferrer">TaskFlow API</a></strong> es mi respuesta de referencia a la pregunta que hacen los entrevistadores: <em>¿qué significa &quot;grado producción&quot; en tu código backend?</em> En vez de responder con adjetivos, publiqué el repositorio — una API donde cada afirmación de seguridad está implementada <strong>y</strong> cubierta por pruebas.</p><h2 id="seguridad-probada-no-prometida" tabindex="-1">Seguridad probada, no prometida <a class="header-anchor" href="#seguridad-probada-no-prometida" aria-label="Permalink to “Seguridad probada, no prometida”">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Implementación</th></tr></thead><tbody><tr><td>Contraseñas</td><td>bcrypt, coste 12, salt por usuario</td></tr><tr><td>Tokens de acceso</td><td>TTL de 15 minutos, HS256 firmado</td></tr><tr><td>Refresh tokens</td><td>Rotación de 7 días con <strong>detección de reuso familiar</strong> — reutilizar un token roto mata toda la familia</td></tr><tr><td>Autorización</td><td>Guardias RBAC como dependencias de FastAPI — <code>require_admin</code>, verificación de propiedad</td></tr><tr><td>Anti-abuso</td><td>Rate limiter de ventana deslizante → <code>429</code> con <code>Retry-After</code></td></tr><tr><td>Higiene ops</td><td>Errores 500 genéricos, <code>X-Request-ID</code>, cabeceras de seguridad, imagen Docker non-root</td></tr></tbody></table><h2 id="decisiones-que-vale-la-pena-robar" tabindex="-1">Decisiones que vale la pena robar <a class="header-anchor" href="#decisiones-que-vale-la-pena-robar" aria-label="Permalink to “Decisiones que vale la pena robar”">​</a></h2><ul><li><strong>Routers delgados, servicios gordos</strong> — la capa HTTP solo parsea y serializa.</li><li><strong>SQLAlchemy 2.0 async + Pydantic v2</strong> — configuración 12-factor; SQLite local, PostgreSQL en compose.</li><li><strong>Docker Compose</strong> con <code>postgres:16</code> y <code>redis:7</code> con healthchecks — <code>docker compose up</code> es toda la guía de instalación.</li><li><strong>Suite pytest que corre en segundos</strong> — base de datos async en memoria, sin contenedores para CI.</li></ul><div class="tip custom-block"><p class="custom-block-title">Pruébalo</p><p><code>docker compose up --build</code> y abre <code>/docs</code> — <a href="https://github.com/Godde3s/taskflow-api" target="_blank" rel="noreferrer">github.com/Godde3s/taskflow-api</a></p></div>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};